#!/usr/bin/env node
// Generates the portal's API types from cmapi/contract/openapi.json, the document that the service serves:
//   src/api/schema.generated.ts       every path, parameter and schema (openapi-typescript)
//   src/api/permissions.generated.ts  the permission of each operation (its x-cmapi-permission)
// With --check it fails if a generated file is out of date. The generator has its own package and lockfile in
// tools/openapi-types, because openapi-typescript 7 needs TypeScript 5 and the app compiles with TypeScript 7.
import { execFileSync } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const app = join(dirname(fileURLToPath(import.meta.url)), "..");
const contract = join(app, "..", "cmapi", "contract", "openapi.json");
const tool = join(app, "tools", "openapi-types", "node_modules", ".bin", "openapi-typescript");
const HEADER = "// Generated by scripts/api-types.mjs from cmapi/contract/openapi.json. Do not edit.\n";

if (!existsSync(tool)) {
  console.error("the generator is not installed: run `npm ci --ignore-scripts` in tools/openapi-types");
  process.exit(1);
}

function schema() {
  const work = mkdtempSync(join(tmpdir(), "cmapi-api-types-"));
  try {
    const out = join(work, "schema.ts");
    execFileSync(tool, [contract, "-o", out], { stdio: ["ignore", "ignore", "inherit"] });
    return HEADER + readFileSync(out, "utf8");
  } finally {
    rmSync(work, { recursive: true, force: true });
  }
}

function permissions() {
  const METHODS = ["get", "post", "put", "patch", "delete"];
  const rows = [];
  for (const [path, item] of Object.entries(JSON.parse(readFileSync(contract, "utf8")).paths)) {
    for (const method of METHODS) {
      const permission = item[method]?.["x-cmapi-permission"];
      // An operation with no permission needs only a valid token (GET /api/v1/me, GET /api/v1/version).
      if (permission) rows.push(`  ${JSON.stringify(`${method.toUpperCase()} ${path}`)}: ${JSON.stringify(permission)},`);
    }
  }
  return `${HEADER}/** The permission that each operation requires, from its x-cmapi-permission. */
export const PERMISSION = {
${rows.sort().join("\n")}
} as const;
`;
}

const files = [
  [join(app, "src", "api", "schema.generated.ts"), schema()],
  [join(app, "src", "api", "permissions.generated.ts"), permissions()]
];
const check = process.argv.includes("--check");
let stale = false;
for (const [path, text] of files) {
  if (!check) writeFileSync(path, text);
  else if (!existsSync(path) || readFileSync(path, "utf8") !== text) {
    console.error(`${path.slice(app.length + 1)} is out of date: run npm run api:types`);
    stale = true;
  }
}
if (stale) process.exit(1);
console.log(check ? "ok - the API types match cmapi/contract/openapi.json" : "wrote the API types");
